grid=[[0,2,2,2,2,2,2,2],[1,8,8,8,8,8,8,8],[1,8,9,9,8,6,6,8],[1,8,9,9,8,6,6,8],[1,8,8,8,8,8,8,8],[1,8,8,8,8,8,8,8],[1,8,1,4,8,9,9,8],[1,8,2,4,8,9,9,8],[1,8,4,4,8,8,8,8],[1,8,4,4,8,8,8,8],[1,8,4,4,8,9,7,8],[1,8,4,4,8,7,9,8],[1,8,8,8,8,7,7,8],[1,8,8,8,8,7,7,8],[1,8,5,4,8,7,7,8],[1,8,5,4,8,7,7,8],[1,8,5,5,8,8,8,8],[1,8,5,5,8,8,8,8],[1,8,8,8,8,8,8,8],[1,8,8,8,8,8,8,8]]
H,W=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  if grid[r][c]==8 or (r,c) in seen: continue
  stack=[(r,c)]; seen.add((r,c)); pts=[]
  while stack:
   x,y=stack.pop(); pts.append((x,y))
   for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
    if 0<=nx<H and 0<=ny<W and grid[nx][ny]!=8 and (nx,ny) not in seen:
     seen.add((nx,ny)); stack.append((nx,ny))
  r0=min(x for x,y in pts); r1=max(x for x,y in pts); c0=min(y for x,y in pts); c1=max(y for x,y in pts)
  crop=[row[c0:c1+1] for row in grid[r0:r1+1]]
  comps.append((r0,c0,r1,c1,crop))
print([(a,b,c,d,len(x),len(x[0])) for a,b,c,d,x in sorted(comps)])
out=[]
for *_,crop in sorted(comps): out.extend(crop)
print(len(out),len(out[0]),out)

